import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';

const Login = () => {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      // Calling the backend API for login
      const res = await axios.post('http://localhost:5000/api/auth/login', { email, password });

      // If successful, save the mock token and go to dashboard
      localStorage.setItem('token', res.data.token);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.error || 'Invalid email or password');
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', backgroundColor: 'var(--light)' }}>
      <div className="bg-white p-5 rounded-4 shadow-sm" style={{ width: '100%', maxWidth: '450px', border: '1px solid var(--border)' }}>
        <div className="text-center mb-4">
          <Link to="/" style={{ textDecoration: 'none', color: 'var(--dark)' }}>
            <h2 className="fw-bold"><i className="fa-solid fa-bolt text-primary"></i> VRX</h2>
          </Link>
          <h3 className="mt-4 fw-bold">Welcome Back</h3>
          <p className="text-muted">Sign in to manage your rentals.</p>
        </div>

        {error && <div className="alert alert-danger py-2">{error}</div>}

        <form onSubmit={handleLogin}>
          <div className="mb-3">
            <label className="form-label fw-bold">Email Address</label>
            <input type="email" required className="form-control p-3 bg-light" placeholder="student@university.edu" value={email} onChange={(e) => setEmail(e.target.value)} />
          </div>
          <div className="mb-4">
            <label className="form-label fw-bold">Password</label>
            <input type="password" required className="form-control p-3 bg-light" placeholder="••••••••" value={password} onChange={(e) => setPassword(e.target.value)} />
          </div>
          <button type="submit" className="btn btn-primary-custom w-100 py-3">Sign In</button>
        </form>

        <div className="text-center mt-4 text-muted">
          Don't have an account? <Link to="/register" className="fw-bold text-primary">Create one</Link>
        </div>
      </div>
    </div>
  );
};

export default Login;
